 function selectEmployeeOfMonth(){const now=new Date(),month=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');const eligible=staff.map(s=>{const sales=orders.filter(o=>(o.status||'completed')==='completed'&&(o.counterPerson||o.shiftPerson)===s.name&&String(o.date||'').slice(0,7)===month);return {staffId:s.id,name:s.name,sales:sales.reduce((n,o)=>n+Number(o.total||0),0),orders:sales.length}}).sort((a,b)=>b.sales-a.sales||b.orders-a.orders);if(!eligible.length||!eligible[0].orders){notify('No completed sales for staff in the current month yet');return}const award={...eligible[0],month,selectedAt:new Date().toISOString()};setEmployeeOfMonth(award);audit('Employee of the month selected',award.name+' · '+month+' · '+money(award.sales));notify('Employee of the month: '+award.name+' (based on recorded completed sales)')}
